import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Research: The Modern ÖVP Power Circles","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/moderne-machtzirkel.md","filePath":"en/recherche/moderne-machtzirkel.md"}'),n={name:"en/recherche/moderne-machtzirkel.md"};function i(s,e,l,h,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="research-the-modern-ovp-power-circles" tabindex="-1">Research: The Modern ÖVP Power Circles <a class="header-anchor" href="#research-the-modern-ovp-power-circles" aria-label="Permalink to &quot;Research: The Modern ÖVP Power Circles&quot;">​</a></h1><p><strong>From &quot;New Style&quot; to a Billion-Dollar Deficit: The Continuation of Pointillism.</strong></p><p>In the modern phase of &quot;The Horten Mystery,&quot; we encounter actors who have translated the legacy of discrete influence into the digital age. While Helmut Horten collected department stores, these actors collected data, posts, and – in the end – a massive budget hole.</p><hr><h2 id="the-key-figures" tabindex="-1">The Key Figures <a class="header-anchor" href="#the-key-figures" aria-label="Permalink to &quot;The Key Figures&quot;">​</a></h2><h3 id="_1-sebastian-kurz-gernot-blumel-the-architects" tabindex="-1">1. Sebastian Kurz &amp; Gernot Blümel: The Architects <a class="header-anchor" href="#_1-sebastian-kurz-gernot-blumel-the-architects" aria-label="Permalink to &quot;1. Sebastian Kurz &amp; Gernot Blümel: The Architects&quot;">​</a></h3><ul><li><strong>The Rise:</strong> &quot;Project Ballhausplatz&quot; was the meticulously planned takeover of the ÖVP.</li><li><strong>The Methods:</strong> Poll manipulation (Beinschab-Tool) and massive advertisement purchases in tabloid media.</li><li><strong>Gernot Blümel:</strong> As the closest confidant and Finance Minister, he made headlines with the &quot;Laptop Affair&quot; and his memory gaps in the U-Committee.</li></ul><h3 id="_2-magnus-brunner-the-deficit-manager" tabindex="-1">2. Magnus Brunner: The Deficit Manager <a class="header-anchor" href="#_2-magnus-brunner-the-deficit-manager" aria-label="Permalink to &quot;2. Magnus Brunner: The Deficit Manager&quot;">​</a></h3><ul><li><strong>The &quot;Budget Hole&quot;:</strong> Under Brunner, the state deficit exploded to <strong>4.7% of GDP</strong> in 2024 – far above the EU Maastricht limit of 3%.</li><li><strong>Inflation:</strong> Austria recorded one of the highest inflation rates in the Eurozone under Brunner.</li><li><strong>The Departure:</strong> At the end of 2024, Brunner moved to Brussels as EU Commissioner, while the &quot;beautified&quot; budget forecasts were debated in Austria.</li></ul><h3 id="_3-wolfgang-sobotka-the-guardian-of-parliament" tabindex="-1">3. Wolfgang Sobotka: The Guardian of Parliament <a class="header-anchor" href="#_3-wolfgang-sobotka-the-guardian-of-parliament" aria-label="Permalink to &quot;3. Wolfgang Sobotka: The Guardian of Parliament&quot;">​</a></h3><ul><li><strong>Role:</strong> As President of the National Council, he chaired the committees of inquiry investigating corruption allegations against his own party.</li><li><strong>Symbolism:</strong> The &quot;Sobotka Organ&quot; (an expensive rented piano in parliament) became a symbol of a detached power elite enjoying luxury at taxpayer expense while inflation hit the people.</li></ul><hr><p><em>Sources: Statistics Austria reports (2024/2025), WKStA investigation files, analysis of the EU deficit procedure against Austria.</em></p>',13)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
